/bin/bash -lc "node --input-type=module - <<'JS'
const s=await (await fetch('https://gravity-ui.com/icons')).text();
for(const term of ['sun','moon','calendar','arrow-down','chart-line','chevron-right','circle-info','person','clock','arrow-up-right','circle-check']) {
 console.log(term, s.match(new RegExp('.{0,30}'+term+'.{0,65}','gi'))?.slice(0,2));
}
JS"

/bin/bash -lc "git diff --check && git diff --stat && node --input-type=module - <<'JS'
import fs from 'node:fs';
const appCss=fs.readFileSync('src/App.css','utf8');
const uikitCss=fs.readFileSync('node_modules/@gravity-ui/uikit/styles/styles.css','utf8');
const tokens=[...new Set(appCss.match(/--g-[a-z0-9-]+/g))];
console.log('Unresolved UI tokens:',tokens.filter(t=>"'!uikitCss.includes(t)));
